class Solution {
public:
    int minMaxDifference(int num) {
        std::string s = std::to_string(num);
        char max_d = ' ';
        for (char ch : s) {
            if (ch != '9') {
                max_d = ch;
                break;
            }
        }
        std::string s_max = s;
        if (max_d != ' ') {
            for (char& ch : s_max) {
                if (ch == max_d) ch = '9';
            }
        }
        char min_d = s[0];
        std::string s_min = s;
        for (char& ch : s_min) {
            if (ch == min_d) ch = '0';
        }
        return std::stoi(s_max) - std::stoi(s_min);
    }
};

class Solution {
    public int minMaxDifference(int num) {
        String s = String.valueOf(num);
        char maxD = ' ';
        for (char ch : s.toCharArray()) {
            if (ch != '9') {
                maxD = ch;
                break;
            }
        }
        String sMax = maxD != ' ' ? s.replace(maxD, '9') : s;
        char minD = s.charAt(0);
        String sMin = s.replace(minD, '0');
        return Integer.parseInt(sMax) - Integer.parseInt(sMin);
    }
}

var minMaxDifference = function(num) {
    const s = String(num);
    let maxD = null;
    for (const ch of s) {
        if (ch !== '9') {
            maxD = ch;
            break;
        }
    }
    const sMax = maxD !== null ? s.replaceAll(maxD, '9') : s;
    const minD = s[0];
    const sMin = s.replaceAll(minD, '0');
    return Number(sMax) - Number(sMin);
};
